api.look('agent');
const cx = api.w/2, cy = 330;
const k = api.seg(t, 0, 1.2);
api.rect(cx-140, cy-70, 280, 150, {c:'fg', w:5, fill:'panel', k, r:12});
api.rect(cx-100, cy-95, 50, 25, {c:'fg', w:4, k:api.seg(t,0.4,1.2)});
api.rect(cx+50, cy-95, 50, 25, {c:'fg', w:4, k:api.seg(t,0.4,1.2)});
api.text('+', cx-75, cy-125, {size:34, c:'bad', weight:'bold', align:'center', k:api.seg(t,0.8,1.4)});
api.text('−', cx+75, cy-125, {size:34, c:'fg', weight:'bold', align:'center', k:api.seg(t,0.8,1.4)});
api.progress(cx-100, cy+20, 200, 24, 0.04, {k:api.seg(t,1,2)});
api.text('Dead', cx, cy+120, {size:40, c:'bad', weight:'bold', align:'center', k:api.seg(t,1.4,2.2)});
api.say('A dead battery', 0.3, 3.2);

api.look('agent');
const cx = api.w/2;
const kA = api.seg(t,0,1.2), kB = api.seg(t,0.8,2);
api.path('M-150 30 L-130 -20 L-70 -50 L40 -50 L100 -10 L150 30 Z', {x:cx, y:200, s:1, c:'fg', w:4, fill:'panel', k:kA});
api.circle(cx-90, 235, 24, {c:'fg', w:4, k:kA, fill:'ink'});
api.circle(cx+90, 235, 24, {c:'fg', w:4, k:kA, fill:'ink'});
api.text('Dead', cx, 150, {size:20, c:'bad', weight:'bold', align:'center', k:kA});
api.path('M-150 30 L-130 -20 L-70 -50 L40 -50 L100 -10 L150 30 Z', {x:cx, y:480, s:1, c:'a2', w:4, fill:'panel', k:kB});
api.circle(cx-90, 515, 24, {c:'a2', w:4, k:kB, fill:'ink'});
api.circle(cx+90, 515, 24, {c:'a2', w:4, k:kB, fill:'ink'});
api.text('Donor', cx, 430, {size:20, c:'a2', weight:'bold', align:'center', k:kB});
api.arrow(cx, 280, cx, 400, {k:api.seg(t,2,3), c:'dim'});
api.callout('Engines off', cx+60, 300, cx+110, 340, {k:api.seg(t,2.8,3.8)});
api.say('Park close. Engines off.', 0.3, 4.8);

api.look('agent');
const cx = api.w/2;
const dead = [cx-90, 220], donor = [cx-90, 560];
api.box(cx-90, 220, 150, 90, {c:'fg', w:4, fill:'panel', k:api.seg(t,0,0.8)});
api.box(cx-90, 560, 150, 90, {c:'a2', w:4, fill:'panel', k:api.seg(t,0,0.8)});
api.text('+', cx-130, 215, {size:30, c:'fg', align:'center', weight:'bold'});
api.text('−', cx-50, 215, {size:30, c:'fg', align:'center', weight:'bold'});
api.text('+', cx-130, 555, {size:30, c:'a2', align:'center', weight:'bold'});
api.text('−', cx-50, 555, {size:30, c:'a2', align:'center', weight:'bold'});
const steps = [
 {n:1, c:'bad', x1:cx-130, y1:560, x2:cx-130, y2:220, bx:cx+60, by:300, s:'Red to dead +'},
 {n:2, c:'bad', x1:cx-130, y1:560, x2:cx-130, y2:560, bx:cx+60, by:420, s:'Red to donor +'},
 {n:3, c:'fg', x1:cx-50, y1:560, x2:cx-50, y2:560, bx:cx+60, by:520, s:'Black to donor −'},
 {n:4, c:'good', x1:cx-50, y1:220, x2:cx-50, y2:220, bx:cx+60, by:200, s:'Black to bare metal'}];
api.curve(cx-130, 560, cx-190, 390, cx-130, 220, {c:'bad', w:6, k:api.seg(t,0.8,2.4)});
api.curve(cx-50, 560, cx+10, 390, cx+110, 120, {c:'fg', w:6, k:api.seg(t,2.6,4.2)});
api.pin(1, cx-130, 220, {k:api.seg(t,0.8,1.6)});
api.pin(2, cx-130, 560, {k:api.seg(t,1.6,2.4)});
api.pin(3, cx-50, 560, {k:api.seg(t,2.6,3.4)});
api.pin(4, cx+110, 120, {k:api.seg(t,3.6,4.4)});
api.text('Red: + to +', cx+90, 340, {size:20, c:'bad', weight:'bold', align:'center', k:api.seg(t,1.4,2.4)});
api.text('Black: last to metal', cx+60, 400, {size:20, c:'fg', weight:'bold', align:'center', k:api.seg(t,3.2,4.4)});
api.scribble(cx+110, 120, 36, 22, {k:api.seg(t,4.4,5.4), c:'good'});
api.say('Red to red. Black to metal.', 0.3, 5.7);

api.look('agent');
const cx = api.w/2, cy = 330;
api.along([[cx-120,cy+120],[cx-120,cy],[cx,cy-80],[cx+120,cy]], 14, t, {c:'accent'});
api.shape('bolt', cx, cy, 150, {c:'warn', fill:'warn', k:api.seg(t,0,1)});
api.glow(cx, cy, 120, {c:'warn'});
api.text('Run donor 3 min', cx, cy+150, {size:26, c:'fg', weight:'bold', align:'center', k:api.seg(t,1,2)});
api.shape('key', cx, cy+250, 70, {c:'a2', k:api.seg(t,2.2,3)});
api.counter(3, cx, cy+250, {k:api.seg(t,1,2.5), suf:' min', size:34});
api.say('Run the donor, then start.', 0.3, 4.8);

api.look('agent');
const cx = api.w/2, cy = 320;
const order = ['Black off metal','Black off donor','Red off donor','Red off dead'];
order.forEach((s,i)=>{
 const k = api.stag(t, i, {gap:0.9, dur:0.7, from:0.2});
 api.node(cx, 150+i*110, 300, 70, s, {k, pop:true, c: i<2?'fg':'bad'});
 api.pin(i+1, cx-175, 150+i*110, {k});
});
api.arrow(cx+170, 150, cx+170, 480, {k:api.seg(t,0.5,3.5), c:'dim'});
api.text('Reverse order', cx, 600, {size:28, weight:'bold', align:'center', c:'good', k:api.seg(t,3.5,4.3)});
api.say('Remove in reverse. Drive 30 minutes.', 0.3, 4.8);
